import database
import gleam/dynamic/decode
import gleam/erlang/atom
import gleam/http/request
import gleam/httpc
import gleam/json
import gleam/result
import gleam/time/timestamp
import webproxy_server/environment

pub type User {
  User(
    id: String,
    display_name: String,
    scopes: List(String),
    organization_id: String,
    created_at: Float,
  )
  SysAdmin(
    id: String,
    display_name: String,
    scopes: List(String),
    organization_id: String,
    created_at: Float,
  )
}

fn json_to_user_decoder() -> decode.Decoder(User) {
  use id <- decode.field("id", decode.string)
  use display_name <- decode.field("displayName", decode.string)
  use scopes <- decode.field("scopes", decode.list(decode.string))
  use organization_id <- decode.field("organization_id", decode.string)
  let created_at = timestamp.system_time() |> timestamp.to_unix_seconds()
  use is_admin <- decode.field("isAdmin", decode.bool)
  case is_admin {
    True ->
      decode.success(SysAdmin(
        id:,
        display_name:,
        scopes:,
        organization_id:,
        created_at:,
      ))
    False ->
      decode.success(User(
        id:,
        display_name:,
        scopes:,
        organization_id:,
        created_at:,
      ))
  }
}

pub fn new_user_table() -> database.Table(User) {
  atom.create("users_table")
  |> database.create_ets_table
}

fn store_user(cache: database.Table(User), token: String, user: User) -> Nil {
  case user {
    // Don't store SysAdmins
    SysAdmin(..) -> Nil
    User(..) -> {
      let _query = {
        use ref <- database.transaction(cache)
        database.upsert(ref, token, user)
      }
      Nil
    }
  }
}

pub fn get_user_by_auth_token(
  cache: database.Table(User),
  token: String,
) -> Result(User, Nil) {
  let query_result = {
    use ref <- database.transaction(cache)
    database.find(ref, token)
  }
  use _ <- result.try_recover(query_result)

  let req = prepare_auth_request(token)

  case httpc.send(req) {
    Ok(resp) if resp.status == 200 -> {
      use user <- result.try(result.replace_error(
        json.parse(resp.body, json_to_user_decoder()),
        Nil,
      ))
      store_user(cache, token, user)
      Ok(user)
    }
    _ -> Error(Nil)
  }
}

fn prepare_auth_request(token: String) {
  let assert Ok(base_req) = request.to(environment.authentication_url())
  request.prepend_header(base_req, "accept", "application/json")
  |> request.prepend_header("authorization", token)
}

