import database
import gleam/dict
import gleam/erlang/atom
import gleam/erlang/process.{type Subject}
import gleam/io
import gleam/json
import gleam/list
import gleam/result
import gleam/string
import gleam/string_tree
import mist
import webproxy_server/auth
import webproxy_server/cluster
import webproxy_server/environment
import webproxy_server/ws.{Authorized, Unauthorized}

pub opaque type PendingResource {
  PendingResource(user_id: String, resource_name: String)
}

pub fn new_pending_resources_queue() -> database.Table(PendingResource) {
  atom.create("pending_resources_table")
  |> database.create_ets_table()
}

fn add_pending_resource_to_queue(
  queue: database.Table(PendingResource),
  user_id: String,
  resource_name: String,
) -> Result(String, database.TransactionError(Nil)) {
  use ref <- database.transaction(queue)
  database.insert(ref, PendingResource(user_id:, resource_name:))
}

pub fn ping(conn: mist.WebsocketConnection, state: ws.WsState) {
  let _ = mist.send_text_frame(conn, "pong")
  mist.continue(state)
}

pub fn subscribe(
  users: database.Table(auth.User),
  clusters: database.Table(cluster.Cluster),
  ip_address: String,
  outbound: Subject(ws.WsCommand),
  auth_token: String,
  connection: mist.WebsocketConnection,
) -> mist.Next(ws.WsState, a) {
  let check = {
    use user <- result.try(auth.get_user_by_auth_token(users, auth_token))

    use cluster_id <- result.try(cluster.join_cluster(
      clusters,
      user,
      ip_address,
      outbound,
    ))

    let _ = mist.send_text_frame(connection, "subscribed")
    Ok(Authorized(user, cluster_id, ip_address, outbound))
  }
  result.unwrap(check, Unauthorized(ip_address, outbound))
  |> mist.continue
}

pub fn require(
  clusters: database.Table(cluster.Cluster),
  pending_resources: database.Table(PendingResource),
  cluster_id: String,
  user: auth.User,
  ip_address: String,
  outbound: Subject(ws.WsCommand),
  resource_name: String,
) {
  let peers =
    cluster.get_connected_peers(clusters, cluster_id, user.id)
    |> dict.values()

  case
    add_pending_resource_to_queue(pending_resources, user.id, resource_name)
  {
    Ok(resource_id) -> {
      let petition =
        json.object([
          #("resourceId", json.string(resource_id)),
          #("scopes", json.array(user.scopes, of: json.string)),
          #("resourceName", json.string(resource_name)),
        ])
        |> json.to_string()
      let petition = "/r " <> petition
      list.each(peers, fn(peer) { process.send(peer, ws.SendText(petition)) })
      process.spawn(fn() {
        process.sleep(60_000)
        remove_pending_resource_from_queue(pending_resources, resource_id)
      })
      Nil
    }
    Error(_) -> {
      io.println_error("Unable to add resource to queue")
    }
  }

  mist.continue(Authorized(user:, cluster_id:, ip_address:, outbound:))
}

fn remove_pending_resource_from_queue(
  queue: database.Table(PendingResource),
  resource_id: String,
) {
  use ref <- database.transaction(queue)
  database.delete(ref, resource_id)
}

pub fn provide(
  clusters: database.Table(cluster.Cluster),
  pending_resources: database.Table(PendingResource),
  cluster_id: String,
  user: auth.User,
  ip_address: String,
  outbound: Subject(ws.WsCommand),
  data: String,
) -> mist.Next(ws.WsState, a) {
  case string.split_once(data, " ") {
    Ok(#(resource_id, response_json)) -> {
      let _ = {
        use ref <- database.transaction(pending_resources)
        case database.find(ref, resource_id) {
          Ok(pending_resource) -> {
            let _ = database.delete(ref, resource_id)
            let peers =
              cluster.get_connected_peers(clusters, cluster_id, user.id)
            case dict.get(peers, pending_resource.user_id) {
              Ok(peer) -> {
                string_tree.from_string("/p ")
                |> string_tree.append(pending_resource.resource_name)
                |> string_tree.append(" ")
                |> string_tree.append(response_js

_id)
            let peers =
              cluster.get_connected_peers(clusters, cluster_id, user.id)
            case dict.get(peers, pending_resource.user_id) {
              Ok(peer) -> {
                string_tree.from_string("/p ")
                |> string_tree.append(pending_resource.resource_name)
                |> string_tree.append(" ")
                |> string_tree.append(response_json)
                |> string_tree.to_string()
                |> ws.SendText
                |> process.send(peer, _)
                Ok(Nil)
              }
              Error(_) -> Ok(Nil)
            }
          }
          Error(_) -> Ok(Nil)
        }
      }
      mist.continue(Authorized(user:, cluster_id:, ip_address:, outbound:))
    }
    _ -> mist.stop()
  }
}

pub fn upgrade(
  user: auth.User,
  ip_address: String,
  conn: mist.WebsocketConnection,
) {
  case user, ip_is_authorized_administrator(ip_address) {
    auth.User(..), _ -> {
      string_tree.from_string("User ")
      |> string_tree.append(user.display_name)
      |> string_tree.append(" from organization ")
      |> string_tree.append(user.organization_id)
      |> string_tree.append(
        " tried to upgrade their connection without an administrator account.",
      )
      |> string_tree.to_string()
      |> io.println_error()
      mist.stop()
    }
    auth.SysAdmin(..), False -> {
      string_tree.from_string("Administrator ")
      |> string_tree.append(user.display_name)
      |> string_tree.append(" tried to upgrade their connection from ")
      |> string_tree.append(ip_address)
      |> string_tree.append(
        ", which is not in the AUTHORIZED_ADMINISTRATOR_IPS list.",
      )
      |> string_tree.to_string()
      |> io.println_error()
      mist.stop()
    }
    auth.SysAdmin(..), True -> {
      let _ =
        mist.send_text_frame(
          conn,
          "Successfully upgraded. You are now in intervention mode.",
        )
      mist.continue(ws.Intervention(user))
    }
  }
}

fn ip_is_authorized_administrator(ip_address: String) -> Bool {
  let authorized = environment.authorized_administrator_ips()
  list.contains(authorized, "*") || list.contains(authorized, ip_address)
}

pub fn on_close(
  clusters: database.Table(cluster.Cluster),
  state: ws.WsState,
) -> Nil {
  case state {
    Authorized(user:, cluster_id:, ..) ->
      cluster.leave_cluster(clusters, cluster_id, user.id)
    _ -> Nil
  }
}

//// Centralizes access to every environment variable the server reads. No other
//// module should call `envoy` directly.

import envoy
import gleam/dynamic/decode
import gleam/int
import gleam/json
import gleam/result
import gleam/string

/// The TCP port the server binds to. Defaults to `8080` when unset or invalid.
pub fn port() -> Int {
  envoy.get("PORT")
  |> result.try(int.parse)
  |> result.unwrap(8080)
}

/// The URL used to authenticate users. Required: the server cannot start
/// without a valid `https://` value.
pub fn authentication_url() -> String {
  let assert Ok("https://" <> url) = envoy.get("AUTHENTICATION_URL")
    as "Please, inform a valid AUTHENTICATION_URL environment variable according to the documentation."

  "https://" <> url
}

/// Whether to trust the transport-level connection IP instead of the
/// `X-Forwarded-For` / `X-Real-IP` headers. Defaults to `False`, which suits a
/// deployment behind a reverse proxy. Set to `True` when the server faces
/// clients directly.
pub fn use_native_connection_ip() -> Bool {
  case envoy.get("USE_NATIVE_CONNECTION_IP") {
    Ok(raw) ->
      case string.lowercase(string.trim(raw)) {
        "true" | "1" -> True
        _ -> False
      }
    Error(_) -> False
  }
}

/// The IP addresses allowed to upgrade to intervention mode, parsed from the
/// `AUTHORIZED_ADMINISTRATOR_IPS` JSON array. A missing, malformed, or empty
/// value yields an empty list, meaning no one is allowed to upgrade.
pub fn authorized_administrator_ips() -> List(String) {
  case envoy.get("AUTHORIZED_ADMINISTRATOR_IPS") {
    Ok(raw) ->
      json.parse(raw, decode.list(decode.string))
      |> result.unwrap([])
    Error(_) -> []
  }
}

# Environment Variables for Web Proxy Server

The `environment.gleam` file is a critical component of the web proxy server project, responsible for managing various environmental variables that control its behavior. This file ensures that the server can start successfully and operate correctly with minimal human intervention.

## Purpose and Role

The `environment.gleam` file contains configuration settings that determine how the server interacts with the outside world. These settings include:

- **Port**: The TCP port on which the server listens for incoming requests.
  - Default: `8080`.
  - Behavior: If not set or invalid, defaults to `8080`.

- **Authentication URL**: The base URL for user authentication.
  - Required: The server cannot start without a valid value.
  - Behavior: If the environment variable is missing or malformed, returns a default value of `"https://"`.

- **Use Native Connection IP**: Determines whether to trust the transport-level connection IP address instead of relying on the `X-Forwarded-For` / `X-Real-IP` headers.
  - Default: `False`.
  - Behavior: Set to `True` when the server faces clients directly, allowing for more control over client authentication.

- **Authorized Administrator IPs**: Specifies a list of IP addresses that are allowed to upgrade to intervention mode.
  - Default: An empty list, meaning no one is allowed to upgrade.
  - Behavior: If the environment variable is missing or malformed, returns an empty list. If the JSON array is empty, returns an empty list.

## Public/Exported Classes, Functions, Constants

### Port

```gleam
/// The TCP port the server binds to. Defaults to `8080` when unset or invalid.
pub fn port() -> Int {
  envoy.get("PORT")
    |> result.try(int.parse)
    |> result.unwrap(8080)
}
```

- **Parameters**: None.
- **Return Value**: An integer representing the port number.
- **Behavior**: If the environment variable is not set or invalid, defaults to `8080`.

